from functools import lru_cache
@lru_cache(None)
def can(n, w):
    if n <= 1: return True
    if w == 0: return False
    return any(can(k, w - 1) and can(n - 2 * k, w - 1) for k in range(1, n // 2 + 1))
ans = max(n for n in range(1, 200) if can(n, 4))

