from collections import deque
from itertools import combinations
n = 5
start = (frozenset(range(n)), 0)
dq = deque([(start, 0)]); seen = {start}
while dq:
    (left, side), d = dq.popleft()
    if not left:
        ans = d; break
    here = left if side == 0 else frozenset(range(n)) - left
    for k in (1, 2):
        for g in combinations(here, k):
            nl = left - set(g) if side == 0 else left | set(g)
            st = (frozenset(nl), 1 - side)
            if st not in seen:
                seen.add(st); dq.append((st, d + 1))

