import math
DIRV = {'N': (0, 1), 'S': (0, -1), 'E': (1, 0), 'W': (-1, 0)}
def name(dx, dy, eps=1e-9):
    ns = 'North' if dy > eps else ('South' if dy < -eps else '')
    ew = 'East' if dx > eps else ('West' if dx < -eps else '')
    return '-'.join(x for x in (ns, ew) if x)
def walk(start, legs):
    x, y = start
    for d, k in legs:
        if d in DIRV:
            ux, uy = DIRV[d]
        else:   # diagonal like 'NE'
            ux = (1 if 'E' in d else -1) / math.sqrt(2); uy = (1 if 'N' in d else -1) / math.sqrt(2)
        x += ux * k; y += uy * k
    return x, y

