        for vals in product('MF', repeat=len(unk)):
            g = dict(s.g); g.update(zip(unk, vals))
            if any(g[a] == g[b] for a, b in s.sp.items() if g[a] and g[b]): continue
            yield g
    def rels(s, x, y):
