def decode(expr):
    toks = expr.strip('$').replace('\\times', '*').replace('\\div', '/').split()
    f = Fam()
    for i in range(1, len(toks), 2):
        a, op, b = toks[i - 1], toks[i], toks[i + 1]
        if op == '+': f.parent(a, b, 'F')
        elif op == '-': f.sib(a, b, 'M')
        elif op == '*': f.spouse(a, b, 'F')
        elif op == '/': f.parent(a, b, 'M')
    # a spouse of a parent is also a parent
    for c in list(f.par):
        for p in list(f.par[c]):
            if p in f.sp: f.par[c].add(f.sp[p])
    for c in list(f.par):            # siblings share the full parent set
        for d in f.sibs(c): f.par[c] |= f.par[d]
    return f
