from itertools import product
class Fam:
    def __init__(s):
        s.g = {}; s.par = {}; s.sp = {}; s.n = 0
    def P(s, *xs):
        for x in xs:
            s.g.setdefault(x, None); s.par.setdefault(x, set())
    def sex(s, x, v):
        s.P(x); assert s.g[x] in (None, v), (x, v); s.g[x] = v
    def parent(s, p, c, v=None):          # p is a parent of c
        s.P(p, c); s.par[c].add(p)
        if v: s.sex(p, v)
    def child(s, c, p, v=None):           # c is a child of p
        s.parent(p, c)
        if v: s.sex(c, v)
    def spouse(s, a, b, va=None):         # a is the husband/wife of b
        s.P(a, b); s.sp[a] = b; s.sp[b] = a
        if va: s.sex(a, va); s.sex(b, 'F' if va == 'M' else 'M')
    def sib(s, a, b, va=None):            # a is a brother/sister of b
        s.P(a, b)
        if not s.par[a] and not s.par[b]:
            s.n += 1; ph = '_p%d' % s.n; s.P(ph); s.par[a].add(ph); s.par[b].add(ph)
        else:
            c = s.par[a] | s.par[b]; s.par[a] |= c; s.par[b] |= c
        if va: s.sex(a, va)
    def kids(s, x): return {c for c, ps in s.par.items() if x in ps}
    def sibs(s, x): return {y for y in s.par if y != x and s.par[x] & s.par[y]}
    def rel(s, x, y, g):
        w = lambda m, f: m if g[x] == 'M' else f
        par = s.par
        if x in par[y]: return w('father', 'mother')
        if y in par[x]: return w('son', 'daughter')
        if x in s.sibs(y): return w('brother', 'sister')
        if s.sp.get(y) == x: return w('husband', 'wife')
        gp = {q for p in par[y] for q in par[p]}
        if x in gp: return w('grandfather', 'grandmother')
        if y in {q for p in par[x] for q in par[p]}: return w('grandson', 'granddaughter')
        au = {q for p in par[y] for q in s.sibs(p)}
        if x in au or x in {s.sp.get(q) for q in au}: return w('uncle', 'aunt')
        au2 = {q for p in par[x] for q in s.sibs(p)}
        if y in au2 or y in {s.sp.get(q) for q in au2}: return w('nephew', 'niece')
        if x in {c for q in au for c in s.kids(q)}: return 'cousin'
        sy = s.sp.get(y)
        if sy and x in par[sy]: return w('father-in-law', 'mother-in-law')
        if any(s.sp.get(c) == x for c in s.kids(y)): return w('son-in-law', 'daughter-in-law')
        if (sy and x in s.sibs(sy)) or any(s.sp.get(b) == x for b in s.sibs(y)): return w('brother-in-law', 'sister-in-law')
        if x in {q for p in gp for q in s.sibs(p)}: return w('grand-uncle', 'grand-aunt')
        return None
    def worlds(s):
        unk = [k for k, v in s.g.items() if v is None and not k.startswith('_')]
        for vals in product('MF', repeat=len(unk)):
            g = dict(s.g); g.update(zip(unk, vals))
            if any(g[a] == g[b] for a, b in s.sp.items() if g[a] and g[b]): continue
            yield g
    def rels(s, x, y):
        return {s.rel(x, y, g) for g in s.worlds()}

